export function getPageMetadataItem(rawPath: string, region: RegionCode = "au"): PageMetaItem | null {
  let cleanPath = (rawPath || "").trim();
  if (cleanPath.startsWith("http://") || cleanPath.startsWith("https://")) {
    try {
      const url = new URL(cleanPath);
      cleanPath = url.pathname;
    } catch {
      cleanPath = cleanPath.replace(/^https?:\/\/[^\/]+/, "");
    }
  }
  cleanPath = cleanPath.replace(/^\/(au|us|ca|nz)(\/|$)/i, "$2") || "/";
  if (!cleanPath.startsWith("/")) cleanPath = "/" + cleanPath;
  if (cleanPath.endsWith("/") && cleanPath.length > 1) cleanPath = cleanPath.slice(0, -1);

  if (region === "au" && AU_MARKET_UNIQUE_META[cleanPath]) {
    return AU_MARKET_UNIQUE_META[cleanPath];
  }

  const entry = PAGE_META_REGISTRY[cleanPath];
  if (entry && entry[region]) {
    return entry[region];
  }

  return null;
}
